do $$ begin
 if not exists (select 1 from pg_roles where rolname='anon') then create role anon nologin; create role authenticated nologin; create role service_role nologin bypassrls; end if; end $$;
create schema auth; create schema extensions; create extension pgcrypto schema extensions;
create table auth.users (id uuid primary key, email text);
create function auth.uid() returns uuid language sql stable as $$ select nullif(nullif(current_setting('request.jwt.claims', true),'')::jsonb ->> 'sub','')::uuid $$;
grant usage on schema auth, extensions, public to anon, authenticated, service_role;
grant execute on all functions in schema auth to anon, authenticated, service_role;
grant execute on all functions in schema extensions to anon, authenticated, service_role;
alter default privileges in schema public grant all on tables to anon, authenticated, service_role;
alter default privileges in schema public grant execute on functions to anon, authenticated, service_role;
create type public.app_role as enum ('admin','rider','distributor');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null, role public.app_role not null, created_at timestamptz default now());
create type public.store_category as enum ('Grocery','Pharmacy','General Store','Supermarket','Cosmetic Store','Other');
create type public.store_payment_terms as enum ('cash','bill_to_bill','credit_25_days');
create type public.order_status as enum ('Pending','Approved','Rejected','Packed','Dispatched','Delivered','Cancelled');
create table public.areas (id uuid primary key default gen_random_uuid(), name text);
create table public.stores (id uuid primary key default gen_random_uuid(), name text not null, owner_name text, mobile text, address text, area text, area_id uuid, category public.store_category, latitude double precision, longitude double precision, image_url text, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now(), name_ur text, gas_customer_id text, payment_terms public.store_payment_terms default 'cash');
create table public.products (id text primary key, name text, category text, vendor_id text, vendor_name text, trade_price numeric, min_stock int, current_stock int, image_url text, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now(), name_ur text, quantity_options int[]);
create table public.customers (id text primary key, name text, open_bal numeric default 0);
create table public.invoices (id text primary key, date date, cust_id text, total numeric, status text);
create table public.payments (id text primary key, date date, type text, amount numeric);
create table public.orders (id uuid primary key default gen_random_uuid(), store_id uuid, rider_id uuid, status public.order_status, total_value numeric, created_at timestamptz default now());
